<?php require_once __DIR__ . '/../includes/bootstrap.php';$u=require_login('employer');$p=database();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p->prepare('UPDATE employers SET company_name=?,description=?,industry=?,website=?,location=?,contact_name=?,contact_phone=? WHERE user_id=?')->execute([posted('company_name'),posted('description')?:null,posted('industry')?:null,posted('website')?:null,posted('location')?:null,posted('contact_name')?:null,posted('contact_phone')?:null,$u['id']]);flash('success','Company profile updated.');redirect('profile.php');}$s=$p->prepare('SELECT * FROM employers WHERE user_id=?');$s->execute([$u['id']]);$e=$s->fetch();page_header('Company profile');?><h1>Company profile</h1><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><?php foreach(['company_name'=>'Company name','industry'=>'Industry','website'=>'Website','location'=>'Location','contact_name'=>'Contact name','contact_phone'=>'Contact phone'] as $key=>$label):?><div><label><?=$label?></label><input name="<?=$key?>" value="<?=e($e[$key])?>" <?= $key==='company_name'?'required':'' ?>></div><?php endforeach;?><div class="full"><label>Description</label><textarea name="description"><?=e($e['description'])?></textarea></div><div class="full"><button>Save profile</button></div></form><?php page_footer(); ?>